<?php
namespace Tests\Feature;
use App\Models\{User,Owner,Venue,EmailDesign};use App\Services\VenueSettings;use App\Services\Email\EmailDesigns;
use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\Mail;use Illuminate\Support\Str;use Tests\TestCase;
class EmailDesignTest extends TestCase {
 use RefreshDatabase;
 private function owner(bool $admin=false):Owner{$u=User::factory()->create();return Owner::unguarded(fn()=>Owner::create(['user_id'=>$u->id,'name'=>'Dueño','email'=>Str::random(8).'@example.com','password'=>'Password12345','activated'=>true,'email_verified_at'=>now(),'platform_admin'=>$admin]));}
 private function venue(Owner $o):Venue{return Venue::create(['owner_id'=>$o->user_id,'owner_account_id'=>$o->id,'name'=>'Jardín Magnolia','slug'=>'jardin-'.Str::lower(Str::random(8)),'published'=>true,'settings'=>VenueSettings::defaults()]);}
 public function test_only_platform_admin_can_edit_global_access_emails():void{$o=$this->owner();$this->actingAs($o)->getJson('/api/owner/email-designs')->assertForbidden();$this->actingAs($this->owner(true))->getJson('/api/owner/email-designs')->assertOk()->assertJsonPath('types.0','verification');$this->putJson('/api/owner/email-designs',['settings'=>['brand_name'=>'Mi plataforma']])->assertOk()->assertJsonPath('settings.brand_name','Mi plataforma');}
 public function test_local_design_is_scoped_and_never_changes_access_templates():void{$o=$this->owner();$v=$this->venue($o);$url='/api/owner/venues/'.$v->slug.'/email-designs';$this->actingAs($o)->putJson($url,['settings'=>['primary'=>'#123456','templates'=>['confirmation'=>['title'=>'Te esperamos en tu evento.']]]])->assertOk();$this->assertSame('#123456',app(EmailDesigns::class)->settings($v)['primary']);$this->assertSame('#285e48',app(EmailDesigns::class)->settings()['primary']);$this->actingAs($this->owner())->getJson($url)->assertForbidden();$this->postJson($url.'/preview',['type'=>'confirmation','settings'=>[]])->assertForbidden();}
 public function test_partial_updates_preserve_other_fields_and_global_style_is_inherited():void{$d=app(EmailDesigns::class);$o=$this->owner(true);$v=$this->venue($o);$this->actingAs($o)->putJson('/api/owner/email-designs',['settings'=>['primary'=>'#112233','footer'=>'Texto personalizado']])->assertOk();$this->assertSame('#112233',$d->settings($v)['primary']);$this->assertSame($v->name,$d->settings($v)['brand_name']);$this->putJson('/api/owner/email-designs',['settings'=>['font'=>'serif']])->assertOk()->assertJsonPath('settings.footer','Texto personalizado')->assertJsonPath('settings.primary','#112233');}
 public function test_preview_renders_actual_template_with_sample_data_without_sending_email():void{$o=$this->owner(true);$this->actingAs($o);Mail::shouldReceive('html')->never();$r=$this->postJson('/api/owner/email-designs/preview',['type'=>'verification','settings'=>['templates'=>['verification'=>['title'=>'Bienvenido, {{cliente}}']]]])->assertOk()->json();$this->assertStringContainsString('Bienvenido, María López',$r['html']);$this->assertStringContainsString('https://example.invalid/vista-previa',$r['html']);$this->assertStringContainsString('una hora',$r['html']);$this->assertDatabaseCount('email_designs',0);}
 public function test_custom_text_is_escaped_and_unsafe_urls_colors_variables_are_rejected():void{$o=$this->owner(true);$this->actingAs($o);$url='/api/owner/email-designs';foreach([['logo_url'=>'javascript:alert(1)'],['primary'=>'red;position:fixed'],['templates'=>['verification'=>['title'=>'{{contraseña}}']]],['templates'=>['recovery'=>['subject'=>"Uno\r\nBcc: other@example.com"]]]] as $data)$this->putJson($url,['settings'=>$data])->assertUnprocessable();$r=$this->postJson($url.'/preview',['type'=>'recovery','settings'=>['templates'=>['recovery'=>['intro'=>'<script>alert(1)</script>']]]])->assertOk()->json();$this->assertStringNotContainsString('<script>',$r['html']);$this->assertStringContainsString('&lt;script&gt;',$r['html']);}
 public function test_confirmation_keeps_money_policy_wifi_and_security_notes():void{$d=app(EmailDesigns::class);$p=$d->sample('confirmation');foreach(['$450.00','$1,050.00','Política de cancelación','no son reembolsables','Red de ejemplo','Cantidad: 80','no es una factura'] as $text)$this->assertStringContainsString($text,$p['html']);$this->assertStringContainsString('VISTA PREVIA',$p['text']);}
 public function test_access_mail_has_html_and_plain_text_and_real_action_url_is_not_customizable():void{$d=app(EmailDesigns::class);Mail::shouldReceive('html')->once()->with(\Mockery::on(fn($html)=>str_contains($html,'https://safe.example/recuperar#restablecer=TOKEN')&&str_contains($html,'Cambiar mi contraseña')),\Mockery::on(function($callback){$m=new \Illuminate\Mail\Message(new \Symfony\Component\Mime\Email());$callback($m);$this->assertSame('cliente@example.com',$m->getSymfonyMessage()->getTo()[0]->getAddress());$this->assertStringContainsString('30 minutos',$m->getSymfonyMessage()->getTextBody());return true;}));$d->sendAccess('recovery','cliente@example.com','Ana','https://safe.example/recuperar#restablecer=TOKEN','El enlace vence en 30 minutos.');}
 public function test_saved_design_is_used_by_real_access_email():void{EmailDesign::create(['scope'=>'platform','settings'=>['templates'=>['verification'=>['title'=>'Confirma tu cuenta de prueba.']]]]);Mail::shouldReceive('html')->once()->with(\Mockery::on(fn($html)=>str_contains($html,'Confirma tu cuenta de prueba.')),\Mockery::type('callable'));app(EmailDesigns::class)->sendAccess('verification','test@example.com','María','https://safe.example/#token=test','Vigente una hora.');}
}
